# Pioneers of Kaggle Town - Checkpoint 1
# More Wheat controller with Demand Preserving robust market-order sequencing.
import base64 as _pk_base64
import zlib as _pk_zlib

_pk_host = {"__name__": "league_more_wheat"}
_pk_donor = {"__name__": "league_demand_new"}
exec(compile(_pk_zlib.decompress(_pk_base64.b64decode('')), "more_wheat", "exec"), _pk_host)
exec(compile(_pk_zlib.decompress(_pk_base64.b64decode('')), "demand_new", "exec"), _pk_donor)
_pk_parent = [v for v in _pk_host.values() if callable(v)][-1]

def agent(obs, cfg):
    action = _pk_parent(obs, cfg)
    action = _pk_donor["_v336_reorder"](obs, action)
    state = _pk_host.get("_RACE_STATE", {}).get(int(obs["player"]))
    if state and state.get("step") == int(obs["step"]) and state.get("prev_action") is not None:
        state["prev_action"] = action
    return action

