#   OPENING: the step-0 wheat trade becomes BUY 6 / SELL 5 (a small round-trip nested
#            inside common rival openings); the rest of the net 5 wheat is bought at step 2.
#   RESERVE: in the first 72 turns, skip a seed purchase that would spend cash the
#            route needs for HIRE orders due within the next 24 turns.
_PK3_BASE = dict(globals())
_PK3_HOST = _PK3_BASE['_pk_host'] if '_pk_host' in _PK3_BASE else _PK3_BASE
_PK3_PARENT = [v for v in list(_PK3_BASE.values()) if callable(v)][-1]
_PK3 = {'__name__': 'pioneers_candidate3_layers'}
exec(compile('# Pioneers exec_guard layer (experiment, 2026-09-23).\n#\n# Wraps an unmodified parent policy (Checkpoint 1) and post-processes only its\n# market list. Two independently switchable mechanisms:\n#\n#  FLOW    Premium sales (MILK, WOOL, STRAWBERRY, MELON) are decided from the\n#          public observation instead of the route tape\'s fixed sale times.\n#          Each turn, for each product, a tick-level (4-turn) market simulation\n#          to the end of the season picks the sell-price threshold P that\n#          maximises our simulated revenue given: exact engine price curves,\n#          exact current town drain plus expected future shop unlocks, our own\n#          supply forecast from our tiles, and a pessimistic rival model (rival\n#          hidden stock, tracked from public tile yields and market-inventory\n#          deltas, plus its tile-forecast supply reaches the market as soon as\n#          it exists). This turn we sell the units whose marginal price >= P.\n#          Sells are placed in the first market slots (lockstep priority).\n#  RESERVE Cash feasibility for the tape: before the market runs, ensure money\n#          after this turn\'s orders covers the tape\'s HIRE/seed/animal/land\n#          purchases over the next 24 turns (FLOW sells more if short) and never\n#          let seed purchases consume cash reserved for hires due within 24\n#          turns (the mechanism behind the episode-112433264 loss).\n#\n# Uses only the agent\'s own observation; no seed, opponent identity or replay.\nimport math\n\nPREMIUM = (\'MILK\', \'WOOL\', \'STRAWBERRY\', \'MELON\')\n_MP = {\n    "WHEAT": (25, 400, "sqrt", 0.80, "log", 0.20),\n    "CARROT": (35, 450, "hinge", 1.00, "sqrt", 0.70),\n    "TOMATO": (60, 200, "hinge", 0.40, "sqrt", 0.60),\n    "STRAWBERRY": (120, 100, "sqrt", 0.70, "linear", 1.60),\n    "MELON": (250, 300, "log", 0.20, "sq", 3.60),\n    "EGG": (50, 332, "hinge", 0.40, "log", 0.20),\n    "MILK": (160, 122, "sqrt", 0.60, "linear", 1.60),\n    "WOOL": (200, 105, "log", 0.20, "sq", 3.20),\n    "FERTILIZER": (100, 200, "linear", 0.40, "linear", 0.40),\n}\n_I0 = 10000\nSHOPS = {\n    "BAKERY": ["EGG", "WHEAT"], "PIZZA_SHOP": ["MILK", "TOMATO", "WHEAT"],\n    "BRUNCH_SPOT": ["EGG", "WHEAT", "STRAWBERRY"], "YARN_STORE": ["WOOL"],\n    "ICE_CREAM_SHOP": ["STRAWBERRY", "MILK", "WHEAT"], "PET_CAFE": ["CARROT"],\n    "SMOOTHIE_SHOP": ["STRAWBERRY", "MILK"],\n    "FARMERS_MARKET": ["WHEAT", "CARROT", "TOMATO", "STRAWBERRY"],\n}\nSEED_COST = {"WHEAT": 10, "CARROT": 20, "TOMATO": 50, "STRAWBERRY": 100, "MELON": 80}\nANIMAL_COST = {"GOOSE": 300, "COW": 400, "SHEEP": 500}\nANIMAL_PRODUCT = {"COW": "MILK", "SHEEP": "WOOL", "GOOSE": "EGG"}\nANIMAL_FIRST = {"COW": 8, "SHEEP": 6, "GOOSE": 4}\nLAND = (1000, 2000, 4000)\nTICK = 4\nLAST_STEP = 718\n\n\ndef _shape(f, x, T):\n    x = max(0.0, x)\n    if f == "linear":\n        return x\n    if f == "sq":\n        return x * x\n    if f == "sqrt":\n        return math.sqrt(x)\n    if f == "log":\n        return math.log(1.0 + x)\n    u = x / T  # hinge\n    return u + 8.0 * max(0.0, u - 1.0) ** 2\n\n\n_AMP = {k: (v[3] * v[0] / _shape(v[2], v[1], v[1]), v[5] * v[0] / _shape(v[4], v[1], v[1])) for k, v in _MP.items()}\n\n\ndef price(item, inv):\n    base, T, bf, _, af, _ = _MP[item]\n    lo, hi = _AMP[item]\n    if inv < _I0:\n        p = base + lo * _shape(bf, _I0 - inv, T)\n    else:\n        p = base - hi * _shape(af, inv - _I0, T)\n    return max(1, int(round(p)))\n\n\ndef _fib(n):\n    a, b = 1, 1\n    for _ in range(n):\n        a, b = b, a + b\n    return a\n\n\ndef _drain(shops, item):\n    return sum((2 if len(SHOPS[s]) == 1 else 1) for s in shops if item in SHOPS.get(s, ()))\n\n\n_UNLOCK_E = {p: sum((2 if len(v) == 1 else 1) for v in SHOPS.values() if p in v) / len(SHOPS) for p in PREMIUM}\n\n\ndef _supply_schedule(farm, step, n_ticks):\n    """Expected future units per tick for each premium product from a farm\'s tiles\n    (held yield counts at tick 0)."""\n    day = step // 24\n    out = {p: [0.0] * n_ticks for p in PREMIUM}\n    for row in farm.get(\'tiles\') or []:\n        for t in row:\n            if not isinstance(t, dict):\n                continue\n            animal = t.get(\'animal\')\n            if animal in (\'COW\', \'SHEEP\'):\n                p = ANIMAL_PRODUCT[animal]\n                out[p][0] += t.get(\'yield_units\', 0) or 0\n                start = max(step, (t.get(\'placed_day\', day) + ANIMAL_FIRST[animal]) * 24)\n                # ~1 unit/day with daily care (base 1 + banked care bonus).\n                for k in range(n_ticks):\n                    s = step + k * TICK\n                    if s >= start:\n                        out[p][k] += TICK / 24.0\n            elif t.get(\'kind\') == \'PLANT\' and t.get(\'crop\') in (\'STRAWBERRY\', \'MELON\'):\n                crop = t[\'crop\']\n                age = day - t.get(\'planted_day\', day)\n                held = t.get(\'yield_units\', 0) or 0\n                if crop == \'MELON\':\n                    units = held if age >= 10 else 6\n                    k = max(0, (10 - age) * 24 - step % 24) // TICK if age < 10 else 0\n                    if k < n_ticks:\n                        out[\'MELON\'][k] += units\n                else:\n                    out[\'STRAWBERRY\'][0] += held\n                    for a in (10, 12, 14, 16):\n                        if a > age:\n                            k = ((a - age) * 24 - step % 24) // TICK\n                            if 0 <= k < n_ticks:\n                                out[\'STRAWBERRY\'][k] += 1.5\n    return out\n\n\ndef _tile_yields(farm):\n    y = {}\n    for j, row in enumerate(farm.get(\'tiles\') or []):\n        for i, t in enumerate(row):\n            if isinstance(t, dict):\n                p = ANIMAL_PRODUCT.get(t.get(\'animal\')) if t.get(\'animal\') else t.get(\'crop\')\n                if p in PREMIUM:\n                    y[(i, j)] = (p, t.get(\'yield_units\', 0) or 0)\n    return y\n\n\ndef _sell_down(item, inv, s, P, force_to=None):\n    """Sell units while price >= P (or down to force_to units). Returns (inv, s, revenue)."""\n    rev = 0.0\n    while s >= 1:\n        p = price(item, inv)\n        if p < P and (force_to is None or s <= force_to):\n            break\n        rev += p\n        s -= 1\n        if p > 1:\n            inv += 1\n    return inv, s, rev\n\n\ndef simulate(item, inv0, stock, ours, rival, drain_tick, center_ticks, unlock_ticks, n_ticks, P, mode, cap):\n    """Our revenue from a threshold-P policy for one item under a rival behaviour:\n    \'flow\'   rival supply hits the market as it appears;\n    \'hold\'   rival hoards and dumps everything in the final tick, ahead of us;\n    \'mirror\' rival uses the same threshold on its own supply and moves first.\n    Our holdings above `cap` (shed room) are sold at any price."""\n    inv = inv0\n    s = stock\n    r = 0.0\n    rev = 0.0\n    for k in range(n_ticks):\n        s += ours[k]\n        last = k == n_ticks - 1\n        if mode == \'flow\':\n            inv += rival[k]\n        else:\n            r += rival[k]\n            if mode == \'mirror\' or last:\n                inv, r, _ = _sell_down(item, inv, r, 0 if last else P)\n        inv, s, got = _sell_down(item, inv, s, 0 if last else P, force_to=cap)\n        rev += got\n        inv -= drain_tick + unlock_ticks[k] + center_ticks[k]\n    return rev\n\n\nclass FlowLayer:\n    def __init__(self, flow=True, reserve=True, planner=\'model\', floor_frac=0.3):\n        self.flow = flow\n        self.planner = planner\n        self.floor_frac = floor_frac\n        self.reserve = reserve\n        self.state = {}\n        self.log = None  # optional list for offline diagnosis\n        self.telemetry = dict(turns=0, flow_changed=0, deferred_units=0, advanced_units=0,\n                              reserve_sells=0, seed_trims=0, room_sells=0, errors=0, max_ms=0.0)\n\n    # --- per-seat tracking -------------------------------------------------\n    def _st(self, player, step):\n        st = self.state.get(player)\n        if st is None or step <= st[\'step\']:\n            st = dict(step=-1, inv=None, our_sold={}, rival_stock={p: 0.0 for p in PREMIUM},\n                      rival_yields=None)\n            self.state[player] = st\n        return st\n\n    def _track(self, st, obs, player, step):\n        market = obs[\'market\'][\'inventory\']\n        rival_farm = obs[\'farms\'][1 - player]\n        yields = _tile_yields(rival_farm)\n        if st[\'inv\'] is not None and st[\'step\'] == step - 1:\n            shops = list(obs[\'town\'].get(\'unlocked_shops\') or [])\n            prev_step = step - 1\n            for p in PREMIUM:\n                drained = 0\n                if prev_step % 4 == 0:\n                    drained += _drain(shops, p)\n                if prev_step % 24 == 0:\n                    drained += 1\n                ours = st[\'our_sold\'].get(p, (0, 0))[1]\n                sold = market[p] - st[\'inv\'][p] + drained - ours\n                st[\'rival_stock\'][p] = max(0.0, st[\'rival_stock\'][p] - max(0, sold))\n            harvested = {p: 0 for p in PREMIUM}\n            for pos, (p, n) in (st[\'rival_yields\'] or {}).items():\n                now = yields.get(pos)\n                cur = now[1] if now and now[0] == p else 0\n                if cur < n:\n                    harvested[p] += n - cur\n            for p in PREMIUM:\n                st[\'rival_stock\'][p] += harvested[p]\n        st[\'rival_yields\'] = yields\n        st[\'inv\'] = {p: market[p] for p in PREMIUM}\n\n    # --- main --------------------------------------------------------------\n    def apply(self, obs, action, projected_shed, tape_future):\n        import time\n        t0 = time.perf_counter()\n        player = int(obs[\'player\'])\n        step = int(obs[\'step\'])\n        st = self._st(player, step)\n        self.telemetry[\'turns\'] += 1\n        self._track(st, obs, player, step)\n        st[\'step\'] = step\n        market = [list(o) for o in (action.get(\'market\') or [])]\n        money = float(obs[\'farms\'][player][\'money\'])\n        prices = obs[\'market\'][\'prices\']\n        inv = obs[\'market\'][\'inventory\']\n        farm = obs[\'farms\'][player]\n\n        parent_q = {}\n        others = []\n        for o in market:\n            if len(o) >= 3 and o[0] == \'SELL\' and o[1] in PREMIUM and self.flow and step < LAST_STEP:\n                parent_q[o[1]] = parent_q.get(o[1], 0) + max(0, int(o[2]))\n            else:\n                others.append(o)\n        if not self.flow or step >= LAST_STEP:\n            parent_q = {}\n\n        q = dict(parent_q)\n        if self.flow and step < LAST_STEP:\n            q = self._plan(obs, player, step, projected_shed, st)\n            if step >= 716:  # never sell less than the parent at the very end\n                for p, n in parent_q.items():\n                    q[p] = max(q.get(p, 0), n)\n            for p in PREMIUM:\n                d = q.get(p, 0) - parent_q.get(p, 0)\n                if d > 0:\n                    self.telemetry[\'advanced_units\'] += d\n                elif d < 0:\n                    self.telemetry[\'deferred_units\'] -= d\n\n        if self.reserve:\n            q, others = self._reserve(obs, player, step, q, others, projected_shed, tape_future, money, prices, inv, farm)\n\n        if self.flow:\n            q = self._room(obs, player, q, projected_shed)\n\n        sells = [[\'SELL\', p, n] for p, n in q.items() if n > 0]\n        sells.sort(key=lambda o: -prices.get(o[1], 0) * o[2])\n        if self.flow:\n            room = 10 - len(others)\n            new_market = sells[:max(0, room)] + others\n        else:\n            new_market = others\n        # sell quantities actually submitted (for rival tracking next turn)\n        st[\'our_sold\'] = {}\n        for o in new_market:\n            if len(o) >= 3 and o[0] == \'SELL\' and o[1] in PREMIUM:\n                n = min(int(o[2]), projected_shed.get(o[1], 0))\n                nonfloor = sum(1 for k in range(n) if price(o[1], inv[o[1]] + k) > 1)\n                st[\'our_sold\'][o[1]] = (n, nonfloor)\n        changed = new_market != market\n        self.telemetry[\'flow_changed\'] += changed\n        self.telemetry[\'max_ms\'] = max(self.telemetry[\'max_ms\'], (time.perf_counter() - t0) * 1000)\n        if not changed:\n            return action\n        out = dict(action)\n        out[\'market\'] = new_market[:10]\n        return out\n\n    def _plan(self, obs, player, step, shed, st):\n        if self.planner == \'eager\':\n            return self._eager(obs, shed)\n        remaining = max(1, LAST_STEP - step)\n        n_ticks = max(1, (remaining + TICK - 1) // TICK)\n        inv = obs[\'market\'][\'inventory\']\n        shops = list(obs[\'town\'].get(\'unlocked_shops\') or [])\n        ours = _supply_schedule(obs[\'farms\'][player], step, n_ticks)\n        riv = _supply_schedule(obs[\'farms\'][1 - player], step, n_ticks)\n        center = [0] * n_ticks\n        for k in range(n_ticks):\n            s0 = step + k * TICK\n            center[k] = sum(1 for s in range(s0, s0 + TICK) if s % 24 == 0)\n        n_shops = len(shops)\n        day = step // 24\n        future_unlock_days = [d for d in range(3, 30, 3) if d > day][:max(0, 8 - n_shops)]\n        # Shed room available to premium stock (per product share, conservative).\n        other = sum(v for k, v in shed.items() if k not in PREMIUM and isinstance(v, (int, float)))\n        cap = max(8, (100 - other - 10) // 2)\n        q = {}\n        for p in PREMIUM:\n            stock = int(shed.get(p, 0))\n            if stock <= 0:\n                q[p] = 0\n                continue\n            # our tile-held units already counted in ours[0]; stock is shed only\n            rival = list(riv[p])\n            rival[0] += st[\'rival_stock\'][p]\n            ul = [0.0] * n_ticks\n            for k in range(n_ticks):\n                d = (step + k * TICK) // 24\n                ul[k] = _UNLOCK_E[p] * sum(1 for u in future_unlock_days if u <= d)\n            drain = _drain(shops, p)\n            here = price(p, inv[p])\n            grid = sorted({max(1, int(here * f)) for f in (0.0, 0.2, 0.35, 0.5, 0.6, 0.7, 0.8, 0.9, 1.0, 1.1, 1.25, 1.5)}\n                          | {max(1, int(_MP[p][0] * f)) for f in (0.25, 0.5, 0.75, 1.0, 1.25)})\n            best, bestP = -1.0, grid[0]\n            results = []\n            for P in grid:\n                rs = [simulate(p, inv[p], stock, ours[p], rival, drain, center, ul, n_ticks, P, mode, cap)\n                      for mode in (\'flow\', \'hold\', \'mirror\')]\n                r = 0.5 * min(rs) + 0.5 * sum(rs) / len(rs)\n                results.append((P, r))\n                if r > best:\n                    best = r\n            # Near-ties go to the LOWER threshold (sell sooner): holding has costs\n            # the model omits (cash, shed room, rivals that pre-empt us).\n            bestP = min(P for P, r in results if r >= best - max(1.0, 0.005 * best))\n            n = 0\n            level = inv[p]\n            while n < stock:\n                pr = price(p, level)\n                if pr < bestP:\n                    break\n                n += 1\n                if pr > 1:\n                    level += 1\n            q[p] = n\n            if self.log is not None:\n                self.log.append((step, p, stock, inv[p] - 10000, here, bestP, n, round(sum(ours[p]), 1),\n                                 round(sum(rival), 1), [(P, int(r)) for P, r in results]))\n        return q\n\n    def _eager(self, obs, shed):\n        # Sell everything available now unless the price is below floor_frac * base\n        # (then wait for town demand to lift it; the final turns sell regardless).\n        inv = obs[\'market\'][\'inventory\']\n        q = {}\n        for p in PREMIUM:\n            stock = int(shed.get(p, 0))\n            floor = self.floor_frac * _MP[p][0]\n            n, level = 0, inv[p]\n            while n < stock and price(p, level) >= floor:\n                if price(p, level) > 1:\n                    level += 1\n                n += 1\n            q[p] = n\n        return q\n\n    def _reserve(self, obs, player, step, q, others, shed, tape_future, money, prices, inv, farm):\n        # Cost of this turn\'s non-premium-sale orders (conservative: SELLs of other\n        # goods are not credited).\n        hires = int(farm.get(\'hires_today\', 0))\n        unlocked = len(farm.get(\'unlocked_quadrants\') or []) - 1\n        spend_now = 0.0\n        kept = []\n        # Reserve for hires due in the next 24 turns (tape), priced by fib.\n        hire_need = 0.0\n        need = 0.0\n        run = 0.0\n        day_hires = {}\n        for k, orders in enumerate(tape_future):\n            s = step + 1 + k\n            d = s // 24\n            for o in orders:\n                if not o:\n                    continue\n                if o[0] == \'HIRE\':\n                    n = day_hires.get(d, hires if d == step // 24 else 0)\n                    c = _fib(n)\n                    day_hires[d] = n + 1\n                    run += c\n                    hire_need += c\n                elif o[0] == \'BUY_SEED\' and len(o) >= 3:\n                    run += SEED_COST.get(o[1], 0) * max(0, int(o[2]))\n                elif o[0] == \'BUY_ANIMAL\' and len(o) >= 3:\n                    run += ANIMAL_COST.get(o[1], 0) * max(0, int(o[2]))\n                elif o[0] == \'BUY_LAND\':\n                    run += LAND[min(2, unlocked)] if unlocked < 3 else 0\n            need = max(need, run)\n        # This turn: walk orders; hires use fib; trim seed buys that would eat the hire reserve.\n        n_h = hires\n        cash = money + sum(self._sale_value(p, n, inv) for p, n in q.items())\n        for o in others:\n            c = 0.0\n            if o and o[0] == \'HIRE\':\n                c = _fib(n_h)\n                n_h += 1\n            elif o and o[0] == \'BUY_SEED\' and len(o) >= 3:\n                c = SEED_COST.get(o[1], 0) * max(0, int(o[2]))\n                if cash - c < hire_need and hire_need > 0 and step < 72:\n                    self.telemetry[\'seed_trims\'] += 1\n                    continue\n            elif o and o[0] == \'BUY_ANIMAL\' and len(o) >= 3:\n                c = ANIMAL_COST.get(o[1], 0) * max(0, int(o[2]))\n            elif o and o[0] == \'BUY_LAND\':\n                c = LAND[min(2, unlocked)] if unlocked < 3 else 0\n            elif o and o[0] == \'BUY_PRODUCT\' and len(o) >= 3:\n                c = prices.get(o[1], 0) * max(0, int(o[2]))\n            elif o and o[0] == \'SELL\' and len(o) >= 3 and o[1] not in PREMIUM:\n                c = -min(int(o[2]), shed.get(o[1], 0)) * prices.get(o[1], 0) * 0.8\n            cash -= c\n            kept.append(o)\n        if self.flow:\n            short = need + 20 - cash\n            while short > 0:\n                # sell the next unit with the highest marginal price\n                cand = [(price(p, inv[p] + q.get(p, 0)), p) for p in PREMIUM\n                        if shed.get(p, 0) > q.get(p, 0)]\n                if not cand:\n                    break\n                pr, p = max(cand)\n                q[p] = q.get(p, 0) + 1\n                short -= pr\n                self.telemetry[\'reserve_sells\'] += 1\n        return q, kept\n\n    def _sale_value(self, p, n, inv):\n        v, level = 0, inv[p]\n        for _ in range(max(0, min(n, 200))):\n            pr = price(p, level)\n            v += pr\n            if pr > 1:\n                level += 1\n        return v\n\n    def _room(self, obs, player, q, shed):\n        total = sum(v for k, v in shed.items() if isinstance(v, (int, float)))\n        carried = sum(sum(v for v in inv.values()) for inv in (obs[\'private\'].get(\'inventories\') or []))\n        sold = sum(q.values())\n        # Carried items reach the shed by DROP or the end-of-day drop; overflow is\n        # discarded in both cases, so keep room for them.\n        limit = 97 - carried\n        excess = total - sold - limit\n        inv = obs[\'market\'][\'inventory\']\n        while excess > 0:\n            cand = [(price(p, inv[p] + q.get(p, 0)), p) for p in PREMIUM if shed.get(p, 0) > q.get(p, 0)]\n            if not cand:\n                break\n            _, p = max(cand)\n            q[p] = q.get(p, 0) + 1\n            excess -= 1\n            self.telemetry[\'room_sells\'] += 1\n        return q\n\n# Opening wheat trade (experiment, 2026-09-24).\n#\n# At step 0 the market processes both players\' order slot i together, unit by\n# unit, so a wheat round-trip nested inside a rival\'s larger one profits from it\n# (episode 112433264: the rival\'s BUY 10 / SELL 10 took $31 from our BUY 20 /\n# SELL 15 and later cost two day-1 hires). The route needs a net 5 wheat, first\n# picked up at step 4. This layer replaces the parent\'s step-0 WHEAT BUY_PRODUCT /\n# SELL orders with [BUY `buy`, SELL `sell`] in the first two market slots and buys\n# the remaining net wheat at step 2. buy=sell=0 is the "quiet" opening.\n# Defaults (6, 5) maximise the worst-case exact step-2 margin over the observed\n# rival openings (tools/opening_grid.py). All other orders are untouched.\nclass QuietOpening:\n    def __init__(self, buy=6, sell=5, later_step=2):\n        self.buy = buy\n        self.sell = sell\n        self.later_step = later_step\n        self.state = {}\n        self.telemetry = dict(quiet_step0_changed=0, quiet_units=0, quiet_buys=0)\n\n    def apply(self, obs, action):\n        player = int(obs[\'player\'])\n        step = int(obs[\'step\'])\n        st = self.state.get(player)\n        if st is None or step <= st[\'step\']:\n            st = self.state[player] = dict(step=-1, pending=0)\n        st[\'step\'] = step\n        market = [list(o) for o in (action.get(\'market\') or [])]\n        if step == 0:\n            net, kept = 0, []\n            for o in market:\n                if len(o) >= 3 and o[1] == \'WHEAT\' and o[0] in (\'BUY_PRODUCT\', \'SELL\'):\n                    n = max(0, int(o[2]))\n                    net += n if o[0] == \'BUY_PRODUCT\' else -n\n                else:\n                    kept.append(o)\n            if kept == market:\n                return action\n            net = max(0, net)\n            buy = min(self.buy, net + self.sell)\n            sell = max(0, min(self.sell, buy))\n            trade = ([[\'BUY_PRODUCT\', \'WHEAT\', buy]] if buy else []) + ([[\'SELL\', \'WHEAT\', sell]] if sell else [])\n            st[\'pending\'] = max(0, net - (buy - sell))\n            self.telemetry[\'quiet_step0_changed\'] += 1\n            self.telemetry[\'quiet_units\'] += st[\'pending\']\n            out = dict(action)\n            out[\'market\'] = (trade + kept)[:10]\n            return out\n        if step == self.later_step and st[\'pending\'] > 0:\n            order = [\'BUY_PRODUCT\', \'WHEAT\', st[\'pending\']]\n            st[\'pending\'] = 0\n            if len(market) >= 10:\n                # Never displace the parent\'s own orders; merge into an existing wheat buy if any.\n                for o in market:\n                    if len(o) >= 3 and o[0] == \'BUY_PRODUCT\' and o[1] == \'WHEAT\':\n                        o[2] = int(o[2]) + order[2]\n                        break\n                else:\n                    return action\n            else:\n                market.insert(0, order)\n            self.telemetry[\'quiet_buys\'] += 1\n            out = dict(action)\n            out[\'market\'] = market\n            return out\n        return action\n', 'pioneers_candidate3_layers', 'exec'), _PK3)
_PK3_LAYER = _PK3['FlowLayer'](flow=False, reserve=True, planner='model')
_PK3_QUIET = _PK3['QuietOpening'](buy=6, sell=5)
_PK3_TELEMETRY = _PK3_LAYER.telemetry


def _pk3_tape_future(player, step, horizon=24):
    chassis = _PK3_HOST['_IMPL'].chassis
    route = (chassis.players.get(player) or {}).get('route', 0)
    out = []
    for t in range(step + 1, min(719, step + 1 + horizon)):
        tape = chassis.routes.get(2 if t >= 648 else route) or chassis.routes.get(route)
        a = tape[t] if tape and t < len(tape) and isinstance(tape[t], dict) else {}
        out.append(a.get('market') or [])
    return out


def pioneers_candidate3_agent(observation, configuration=None):
    action = _PK3_PARENT(observation, configuration)
    original = action
    try:
        player = int(observation['player'])
        step = int(observation['step'])
        action = _PK3_QUIET.apply(observation, action)
        chassis = _PK3_HOST['_IMPL'].chassis
        view = _PK3_HOST['_View'](observation, player, chassis.cfg)
        projected = chassis._projected_shed(action, view)
        action = _PK3_LAYER.apply(observation, action, projected, _pk3_tape_future(player, step))
        if action is not original:
            state = _PK3_HOST.get('_RACE_STATE', {}).get(player)
            if state and state.get('step') == step and state.get('prev_action') is not None:
                state['prev_action'] = action
    except Exception:
        _PK3_LAYER.telemetry['errors'] += 1
        action = original
    _PK3_TELEMETRY.update(_PK3_QUIET.telemetry)
    return action
